#!/usr/bin/env node
/**
 * Guards the one way the frozen LESS→CSS migration table can still become wrong.
 *
 * WHY THIS EXISTS
 *   `doc/migration/less-var-to-token.md` tells a customer who customized the LESS theme which
 *   `--zk-*` custom property replaces each `@variable` they overrode. It was generated by
 *   `gen-var-table.js`, which was retired at P8 together with the `.less` sources it measured.
 *   The table is frozen — but only its LEFT column is safe. No new `.less` variable can ever
 *   appear in this repository, so no new row can ever be needed; the RIGHT column, however,
 *   names tokens that are still live and still edited. Rename or delete one and the table starts
 *   pointing at something that does not exist, with nothing to say so.
 *
 * THIS CHECK IS DELIBERATELY ONE-DIRECTIONAL
 *   The retired generator asserted BOTH directions: every token the table names must be declared
 *   (`tokensWithoutProfile: 0`) AND every declared token must be named by some variable
 *   (`unmappedProfileTokens: 0`). Only the first survives here, and dropping the second is the
 *   point rather than an omission.
 *
 *   The second assertion made sense only while the theme was a 1:1 conversion of a LESS theme,
 *   where every token by construction had a LESS ancestor. A token added from now on has no
 *   ancestor and therefore nothing to migrate FROM — listing it would be noise, and asserting it
 *   must be listed would fail every future token addition. That is not hypothetical: the 20
 *   `@severity*` tokens tripped exactly that assertion, and the reason they genuinely belonged in
 *   the table (they DID have LESS ancestors, backfilled from ZK 10.4) is a property of those
 *   tokens, not something the assertion could tell.
 *
 * WHY THE DEFAULT PROFILE SPECIFICALLY, NOT "DECLARED ANYWHERE"
 *   The advice each row gives is "override this property instead". That advice only works where
 *   the token is declared at `:root` by the profile the theme actually ships, so the anchor is
 *   `_default.css` alone.
 *
 *   Two laxer readings were rejected because each has a live failure mode they would wave
 *   through. "Declared anywhere in the theme" would accept a token that moved from a profile into
 *   a component file — but a component-local `--zk-*` declaration shadows a `:root` override, so
 *   every row naming it would be quietly wrong. "Declared by any file in the profile directory"
 *   would accept a token dropped from `_default.css` while `_compact.css` keeps it, which is
 *   precisely a rename half-done. Both still get named in the failure output, because knowing
 *   WHERE a token went is most of the fix.
 *
 * WHAT THIS CHECK DOES NOT DO
 *   It does not ask whether a token is CONSUMED. A declared-but-unused token makes overriding it
 *   a no-op, which the table already records per row (`rowsDeadNameButLiveToken`,
 *   `rowsDeadOnBothSides`) from a measurement this repository can no longer repeat.
 *
 * EXIT CODE  0 = every token the table names is still declared by the default profile, 1 = at
 *            least one is not, 2 = the table or the tree could not be read.
 */
const fs = require('fs');
const path = require('path');
const { stripComments } = require('./build-css');

const REPO = path.resolve(__dirname, '..');
const TABLE = path.join(REPO, 'doc/migration/less-var-to-token.json');
const DEFAULT_WEB = path.join(REPO, 'src/main/resources/web');
const PROFILE_SUBDIR = 'zul/css/tokens';
const DEFAULT_PROFILE = '_default.css';

const DECL_RE = /^[ \t]*(--zk-[A-Za-z0-9-]+)[ \t]*:/gm;

function fail(msg) {
	console.error(`check-migration-tokens: ${msg}`);
	process.exit(2);
}

/** `--src <web-root>` and `--table <file>` exist so the negative tests can run against a throwaway
 *  copy of the tree; nothing may verify a guard by mutating the real sources. */
function parseArgs(argv) {
	let web = DEFAULT_WEB, table = TABLE;
	for (let i = 0; i < argv.length; i++) {
		if (argv[i] === '--src') web = path.resolve(argv[++i]);
		else if (argv[i] === '--table') table = path.resolve(argv[++i]);
		else fail(`unknown option: ${argv[i]}\nusage: check-migration-tokens.js [--src <web-root>] [--table <json>]`);
	}
	return { web, table };
}

/** Every `--zk-*` declaration in the theme, as token -> [web-relative file]. Comments are stripped
 *  first, so a commented-out declaration cannot keep a deleted token alive. */
function declarationsIn(web) {
	if (!fs.existsSync(web)) fail(`no such directory: ${web}`);
	const out = new Map();
	const walk = (dir) => {
		for (const e of fs.readdirSync(dir, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {
			const p = path.join(dir, e.name);
			if (e.isDirectory()) walk(p);
			else if (e.name.endsWith('.css')) {
				const css = stripComments(fs.readFileSync(p, 'utf8'));
				const rel = path.relative(web, p).split(path.sep).join('/');
				for (const m of css.matchAll(DECL_RE)) {
					if (!out.has(m[1])) out.set(m[1], []);
					if (!out.get(m[1]).includes(rel)) out.get(m[1]).push(rel);
				}
			}
		}
	};
	walk(web);
	return out;
}

const { web, table: tablePath } = parseArgs(process.argv.slice(2));
const shown = (p) => path.relative(REPO, p) || p;

if (!fs.existsSync(tablePath)) fail(`no such file: ${shown(tablePath)}`);
let table;
try {
	table = JSON.parse(fs.readFileSync(tablePath, 'utf8'));
} catch (e) {
	fail(`${shown(tablePath)} is not valid JSON — ${e.message}`);
}
if (!Array.isArray(table.rows)) fail(`${shown(tablePath)} has no rows array`);

const ANCHOR = `${PROFILE_SUBDIR}/${DEFAULT_PROFILE}`;
const declared = declarationsIn(web);
if (!fs.existsSync(path.join(web, ANCHOR))) fail(`no such file: ${ANCHOR} under ${web}`);
const anchored = new Set([...declared].filter(([, files]) => files.includes(ANCHOR)).map(([t]) => t));

// token -> the rows that would go wrong if it disappeared
const named = new Map();
for (const row of table.rows) {
	for (const token of row.tokens || []) {
		if (!named.has(token)) named.set(token, []);
		named.get(token).push(row.lessVariable);
	}
}

const missing = [...named.keys()].filter((t) => !anchored.has(t)).sort();

console.log(`frozen table:              ${shown(tablePath)}`);
console.log(`rows:                      ${table.rows.length}`);
console.log(`distinct tokens named:     ${named.size}`);
console.log(`anchor profile:            ${ANCHOR}`);
console.log(`tokens it declares:        ${anchored.size}`);
console.log(`named but NOT declared:    ${missing.length}`);

for (const token of missing) {
	const rows = named.get(token);
	const elsewhere = declared.get(token) || [];
	console.log(`    !!! ${token} — named by ${rows.length} row(s): ${rows.slice(0, 4).join(', ')}` +
		`${rows.length > 4 ? `, +${rows.length - 4} more` : ''}`);
	if (!elsewhere.length) {
		console.log('        declared nowhere in the theme — renamed or deleted.');
	} else if (elsewhere.every((f) => f.startsWith(`${PROFILE_SUBDIR}/`))) {
		console.log(`        still declared in ${elsewhere.join(', ')} — dropped from the default profile\n` +
			'        only, which is a half-done rename: default-profile users lose it.');
	} else {
		console.log(`        still declared in ${elsewhere.join(', ')} — a component-local declaration\n` +
			'        shadows a :root override, so the row\'s "override this property" advice no longer holds.');
	}
}

if (missing.length) {
	console.log(
		`\nFAIL — ${missing.length} token(s) the migration table names are no longer declared by the\n` +
		'default profile. Either restore them, or update the affected rows in\n' +
		'doc/migration/less-var-to-token.{md,json} (the table is frozen and hand-maintained since P8;\n' +
		'see its `addendum`). Adding a NEW token never trips this check — only renaming or deleting\n' +
		'one the table already points at.');
	process.exit(1);
}
console.log(`\nOK — every token the frozen migration table names is still declared by ${ANCHOR}.`);
